	    BenefitEnrollment parentEntity = repository.findById(parentId).get();
	    Dependent child = registry.project( Dependent.class, removeFrom.getDependentId());
	    
	    parentEntity.getDependents().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
